actions": 45}}, {"media_id": "17924796714431453", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-15T19:11:20+0000", "permalink": "https://www.instagram.com/p/DehrePumr22/", "shortcode": "DehrePumr22", "caption": "Loafer Suede. 🤎\nGamuza suave, hechos a mano y con ese estilo que hace que todo se vea bien sin pensarlo demasiado.\n\nCómodos, relajados y muy Fuxia.\n\nConsíguelos en el link de abajo o comenta FUXIA y te mandamos el enlace.", "metrics": {"reach": 1357, "views": 2688, "likes": 24, "comments": 7, "saves": 6, "shares": 1, "total_interactions": 38}}, {"media_id": "18106049149982052", "kind": "post", "media_type": "IMAGE", "media_product_type": "FEED", "posted_at": "2026-10-14T22:35:38+0000", "permalink": "https://www.instagram.com/p/DefdupXB1PU/", "shortcode": "DefdupXB1PU", "caption": "Algo chiquito se está preparando… 👀\n\nPróximamente llega Fuxia Kids: pares tan cool y cómodos como los de las grandes, pero hechos para las pequeñas de la casa. \n\nEspérate a ver los modelos, se vienen demasiado lindos. 🎀", "metrics": {"reach": 2501, "views": 4224, "likes": 55, "comments": 6, "saves": 4, "shares": 7, "total_interactions": 72, "profile_visits": 74, "follows": 12}}, {"media_id": "17970374366960656", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-14T13:37:16+0000", "permalink": "https://www.instagram.com/p/DeegcoRGm8p/", "shortcode": "DeegcoRGm8p", "caption": "Ven, pruébatelos todos y encuentra ese par que se siente hecho para ti. \nTe esperamos en Campos Elíseos 158, Polanco y Av. Contreras 516, San Jerónimo, CDMX.\n\n¿Prefieres recibirlos en casa? Compra en el enlace de abajo y disfruta envío gratis.", "metrics": {"reach": 2172, "views": 4433, "likes": 29, "comments": 0, "saves": 5, "shares": 0, "total_interactions": 34}}, {"media_id": "18129295414704044", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-13T23:27:33+0000", "permalink": "https://www.instagram.com/p/Dec_NGTGpJW/", "shortcode": "Dec_NGTGpJW", "caption": "De la mañana a la noche, van contigo a donde sea. \n\nSandalias planas, cómodas y con ese algo que hace que todos volteen a ver.\n\nDescubre nuestras sandalias y más en el enlace de abajo o comenta Fuxia y te mandamos el enlace.", "metrics": {"reach": 1716, "views": 3561, "likes": 24, "comments": 1, "saves": 0, "shares": 0, "total_interactions": 25}}, {"media_id": "18015673577971597", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-13T13:08:25+0000", "permalink": "https://www.instagram.com/p/Deb4WaaoARK/", "shortcode": "Deb4WaaoARK", "caption": "Mafalda Taches Gamuza ✨\n\nSuaves, sofisticadas y con la dosis exacta de actitud. La gamuza genuina se encuentra con tachones plateados y una hebilla lateral que hace que cualquier look se vea mucho más interesante.\n\nDe jeans a algo más arreglado, son ese par que eleva todo sin esfuerzo.\n\nConsíguelas en el enlace de abajo o comenta FUXIA y te mandamos el link.", "metrics": {"reach": 1357, "views": 2588, "likes": 22, "comments": 1, "saves": 2, "shares": 0, "total_interactions": 25}}, {"media_id": "18140838163618865", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-12T17:06:59+0000", "permalink": "https://www.instagram.com/p/DeZu26hGuW3/", "shortcode": "DeZu26hGuW3", "caption": "Comb 🤎\nBotas estilo vaquero en gamuza y piel, hechas para llevar tu look un paso más allá.\n\nYa sea en la ciudad o en ese lugar donde se sienten mejor los fines de semana, son ese par que transforma cualquier outfit y le pone toda la actitud.\n\nConsíguelas en el enlace al final de este post o comenta FUXIA y te mandamos el link.", "metrics": {"reach": 754, "views": 1508, "likes": 8, "comments": 1, "saves": 1, "shares": 1, "total_interactions": 11}}, {"media_id": "17912877933288429", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-11T19:33:29+0000", "permalink": "https://www.instagram.com/p/DeXa1A1milT/", "shortcode": "DeXa1A1milT", "caption": "Fawn Flat 🦌\nBambi vibes, big attitude.\n\nHecha a mano en piel con pelo, print de lunares y hebilla dorada. Cómoda desde el primer paso y perfecta para darle ese toque especial a cualquier look.\n\nComenta FUXIA y te mandamos el link.", "metrics": {"reach": 1396, "views": 2929, "likes": 26, "comments": 1, "saves": 7, "shares": 1, "total_interactions": 37}}, {"media_id": "18141817525612853", "kind": "reel", "media_type": "VIDEO", "media_product_type": "REELS", "posted_at": "2026-10-11T14:20:14+0000", "permalink": "https://www.instagram.com/reel/DeW26K5NReU/", "shortcode": "DeW26K5NReU", "caption": "Comenta: Quiero mi App y te la enviamos por DM!\n\nCada compra suma y te acerca a beneficios exclusivos. \n\nDescárgala, conócela y disfruta todo lo que tenemos preparado para ti.", "metrics": {"reach": 1286, "views": 1676, "likes": 35, "comments": 15, "saves": 2, "shares": 0, "total_interactions": 52, "avg_watch_ms": 6206}}, {"media_id": "18028789223877503", "kind": "reel", "media_type": "VIDEO", "media_product_type": "REELS", "posted_at": "2026-10-10T18:27:06+0000", "permalink": "https://www.instagram.com/reel/DeUuXLyso3y/", "shortcode": "DeUuXLyso3y", "caption": "Hay cosas que todavía se hacen como antes: con las manos, con tiempo y cuidando cada detalle.\n\nAsí nace cada par de Fuxia. Detrás de cada corte, cada costura y cada acabado hay manos expertas y una historia que queremos que lleves contigo.\n\nHechos a mano. Hechos con amor. Hechos para ti.\n\nEsto es Fuxia. ❤️", "metrics": {"reach": 1428, "views": 1751, "likes": 16, "comments": 0, "saves": 1, "shares": 0, "total_interactions": 18, "avg_watch_ms": 5031}}, {"media_id": "18112910795165654", "kind": "carousel", "media_type": "CAROUSEL_ALBUM", "media_product_type": "FEED", "posted_at": "2026-10-10T14:29:14+0000", "permalin